-- 000017_nhsa_drug_catalog.up.sql
-- 国家医保药品目录（2024年版）参考数据
-- 数据来源: 国家医保局《国家基本医疗保险、工伤保险和生育保险药品目录（2024年）》
-- 提取自官方PDF，共 3313 条（西药+中成药，按药品名称+剂型去重）
-- 用途: 药品名称模糊搜索/自动补全, 医保类别筛选

-- 国家医保药品目录表
CREATE TABLE nhsa_drug_catalog (
    id              BIGSERIAL PRIMARY KEY,
    drug_name       VARCHAR(200) NOT NULL,
    dosage_form     VARCHAR(80),
    insurance_class VARCHAR(4)  NOT NULL,
    drug_category   VARCHAR(100),
    sub_category    VARCHAR(100),
    is_essential    BOOLEAN NOT NULL DEFAULT FALSE,
    py_code         VARCHAR(80),
    notes           VARCHAR(500),
    status          SMALLINT NOT NULL DEFAULT 1,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_nhsa_name ON nhsa_drug_catalog (drug_name);
CREATE INDEX idx_nhsa_py ON nhsa_drug_catalog (py_code);
CREATE INDEX idx_nhsa_class ON nhsa_drug_catalog (insurance_class);
CREATE INDEX idx_nhsa_category ON nhsa_drug_catalog (drug_category);

